import { defineConfig, devices } from '@playwright/test'

export default defineConfig({
  testDir: './tests',
  fullyParallel: true,
  reporter: 'list',
  use: {
    baseURL: 'http://127.0.0.1:4173',
    trace: 'on-first-retry',
  },
  webServer: {
    command: 'npm run dev -- --host 127.0.0.1',
    url: 'http://127.0.0.1:4173',
    reuseExistingServer: !process.env.CI,
  },
  projects: [
    {
      name: 'chromium',
      use: { ...devices['Desktop Chrome'] },
    },
  ],
})

import { test } from '@playwright/test'
import { expect } from '@wcag-tools/playwright'

const productUrl = '/products/trail-runner-2'

test.describe('Trail Runner 2 product page', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto(productUrl)
  })

  test('shows the store, cart count, product title, price, and main navigation', async ({ page }) => {
    await expect(page.getByRole('banner')).toContainText('Stride')
    await expect(page.getByRole('link', { name: /cart/i })).toContainText(/\d+/)
    await expect(page.getByRole('heading', { level: 1, name: 'Trail Runner 2' })).toBeVisible()
    await expect(page.getByText(/\$\s?\d+/)).toBeVisible()

    const navigation = page.getByRole('navigation', { name: /main/i })
    await expect(navigation.getByRole('link', { name: /men/i })).toBeVisible()
    await expect(navigation.getByRole('link', { name: /women/i })).toBeVisible()
    await expect(navigation.getByRole('link', { name: /kids/i })).toBeVisible()
  })

  test('provides an accessible breadcrumb with links to earlier steps', async ({ page }) => {
    const breadcrumb = page.getByRole('navigation', { name: /breadcrumb/i })

    await expect(breadcrumb).toBeAPGBreadcrumb()
    await expect(breadcrumb.getByRole('link', { name: 'Shop' })).toBeVisible()
    await expect(breadcrumb.getByRole('link', { name: 'Trail' })).toBeVisible()
    await expect(breadcrumb).toContainText('Trail Runner 2')
  })

  test('shows one product photo and wraps carousel controls', async ({ page }) => {
    const carousel = page.getByRole('region', { name: /product photos/i })

    await expect(carousel).toBeAPGCarousel()
    await expect(carousel.getByRole('button', { name: /previous/i })).toBeVisible()
    await expect(carousel.getByRole('button', { name: /next/i })).toBeVisible()
    await expect(carousel.locator('[aria-current="true"], [aria-hidden="false"]')).toHaveCount(1)
  })

  test('explains that the price includes taxes with a tooltip', async ({ page }) => {
    const priceInfo = page.getByRole('button', { name: /price.*tax|tax.*price/i })

    await expect(priceInfo).toBeAPGTooltip(/tax/i)
  })

  test('lets the shopper choose exactly one color', async ({ page }) => {
    const colors = page.getByRole('radiogroup', { name: /color/i })

    await expect(colors).toBeAPGRadioGroup()
    await expect(colors.getByRole('radio', { name: /blue/i })).toBeVisible()
    await expect(colors.getByRole('radio', { name: /black/i })).toBeVisible()
    await expect(colors.getByRole('radio', { name: /grey|gray/i })).toBeVisible()

    await colors.getByRole('radio', { name: /black/i }).click()
    await expect(colors.getByRole('radio', { name: /black/i })).toBeChecked()
    await expect(colors.getByRole('radio', { name: /blue/i })).not.toBeChecked()
  })

  test('opens a size list, exposes the selected size, and disables sold-out sizes', async ({ page }) => {
    const size = page.getByRole('combobox', { name: /size/i })

    await expect(size).toBeAPGCombobox()
    await expect(size).toHaveAttribute('aria-expanded', 'false')
    await size.press('Enter')
    await expect(size).toHaveAttribute('aria-expanded', 'true')
    await expect(page.getByRole('option', { name: /sold out/i })).toBeDisabled()
  })

  test('opens a size guide dialog and calculates a size from foot length and unit', async ({ page }) => {
    const guide = page.getByRole('button', { name: /size guide/i })

    await guide.click()
    const dialog = page.getByRole('dialog', { name: /size guide/i })
    await expect(dialog).toBeVisible()
    await expect(guide).toBeAPGModal(['role-and-name', 'modal', 'focus-moves-in', 'escape-closes', 'focus-returns'])

    await dialog.getByRole('spinbutton', { name: /foot length/i }).fill('26')
    await dialog.getByRole('radio', { name: /eu/i }).check()
    await dialog.getByRole('button', { name: /calculate|find.*size/i }).click()
    await expect(dialog).toContainText(/size/i)

    await dialog.getByRole('button', { name: /close/i }).click()
    await expect(dialog).toBeHidden()
  })

  test('supports quantity typing and one-step increment/decrement', async ({ page }) => {
    const quantity = page.getByRole('spinbutton', { name: /quantity/i })

    await expect(quantity).toBeAPGSpinbutton()
    await quantity.fill('2')
    await expect(quantity).toHaveValue('2')
    await page.getByRole('button', { name: /increase quantity|add one/i }).click()
    await expect(quantity).toHaveValue('3')
    await page.getByRole('button', { name: /decrease quantity|remove one/i }).click()
    await expect(quantity).toHaveValue('2')
  })

  test('requires a size before adding to cart and confirms a successful add', async ({ page }) => {
    const addToCart = page.getByRole('button', { name: /add to cart/i })

    await addToCart.click()
    await expect(page.getByRole('alert')).toContainText(/pick.*size|select.*size/i)

    await page.getByRole('combobox', { name: /size/i }).press('Enter')
    await page.getByRole('option', { name: /^(?!.*sold out).+/i }).first().click()
    await addToCart.click()
    await expect(page.getByRole('status')).toContainText(/added.*cart|cart.*updated/i)
  })

  test('toggles the shoe in the wishlist', async ({ page }) => {
    const wishlist = page.getByRole('button', { name: /wishlist|save/i })

    await expect(wishlist).toHaveAttribute('aria-pressed', 'false')
    await wishlist.click()
    await expect(wishlist).toHaveAttribute('aria-pressed', 'true')
    await wishlist.click()
    await expect(wishlist).toHaveAttribute('aria-pressed', 'false')
  })

  test('switches between details, reviews, and shipping panels', async ({ page }) => {
    const tabs = page.getByRole('tablist', { name: /product information|more information/i })

    await expect(tabs).toBeAPGTabs()
    await expect(tabs.getByRole('tab', { name: /details/i })).toHaveAttribute('aria-selected', 'true')
    await tabs.getByRole('tab', { name: /reviews/i }).click()
    await expect(tabs.getByRole('tab', { name: /reviews/i })).toHaveAttribute('aria-selected', 'true')
    await expect(page.getByRole('tabpanel')).toContainText(/review/i)
    await tabs.getByRole('tab', { name: /shipping/i }).click()
    await expect(tabs.getByRole('tab', { name: /shipping/i })).toHaveAttribute('aria-selected', 'true')
  })

  test('reveals answers to common questions on demand', async ({ page }) => {
    const questions = page.getByRole('region', { name: /questions|faq/i })

    await expect(questions).toBeAPGAccordion()
    const question = questions.getByRole('button').first()
    await expect(question).toHaveAttribute('aria-expanded', 'false')
    await question.click()
    await expect(question).toHaveAttribute('aria-expanded', 'true')
    await expect(questions.getByRole('region').first()).toBeVisible()
  })

  test('includes customer help, company, and social links in the footer', async ({ page }) => {
    const footer = page.getByRole('contentinfo')

    await expect(footer).toBeVisible()
    await expect(footer.getByRole('link', { name: /help|contact|support/i })).toBeVisible()
    await expect(footer.getByRole('link', { name: /company|about/i })).toBeVisible()
    await expect(footer.getByRole('link', { name: /instagram|facebook|twitter|social/i })).toBeVisible()
  })

  test('meets WCAG 2.2 AA in the default product-page state', async ({ page }) => {
    await expect(page).toBeWCAGCompliant()
  })
})

